entries[56935] = { ["name"] = "Eisnova", ["text"] = "Wirken in 2 sek.\nVerursacht bei allen Feinden innerhalb von 60 Metern 3299 to 3701 Frostschaden und betäubt sie 3 Sek. lang." }
entries[56936] = { ["name"] = "Blizzard", ["text"] = "200 Mana 40 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nRuft einen Blizzard herbei, der 6 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 2000 Frostschaden zufügt." }
