entries[56969] = { ["name"] = "Arkanschlag", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Energie und verursacht 4375 to 5625 Arkanschaden. Jedes Mal, wenn Ihr 'Arkanschlag' wirkt, verringert sich die Zauberzeit. Dieser Effekt ist bis zu 5-mal stapelbar und hält 8 Sek. lang an." }
