entries[56972] = { ["name"] = "Glyphe 'Arkane Macht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nAstraltinte (3), Widerstandsfähiges Pergament\nKlassen: Magier\n69\nBenutzen:\nWährend 'Arkane Macht' aktiv ist, haben Eure Zauber 'Blinzeln', 'Manaschild' und 'Spiegelbild' keine globale Abklingzeit." }
