entries[57933] = { ["name"] = "Schurkenhandel", ["text"] = "100 Meter Reichweite\nSofort\nDas gewählte Gruppen- oder Schlachtzugsmitglied wird das Ziel Eures Schurkenhandels. Die von Eurem nächsten Angriff erzeugte Bedrohung sowie aller innerhalb von 6 Sek. danach erfolgenden Aktionen wird auf das Ziel übertragen. Zusätzlich wird jeglicher verursachte Schaden des Ziels in dieser Zeit um 15% erhöht." }
entries[57934] = { ["name"] = "Schurkenhandel", ["text"] = "15 Energie 100 Meter Reichweite\nSofort 30 sek. Abklingzeit\nDie von Eurem nächsten Schaden verursachenden Angriff erzeugte Bedrohung sowie aller innerhalb von 6 Sek. danach erfolgenden Aktionen wird auf das ausgewählte Gruppen- oder Schlachtzugsmitglied übertragen. Zusätzlich wird jeglicher verursachte Schaden dieses Verbündeten während dieser Zeit um 15% erhöht. Die übertragene Bedrohung ist nicht permanent, sondern verlischt nach 30 Sek." }
